function fit(){if(!active)return;active.arrival?.finish();const box=new T.Box3().setFromObject(active.group),size=box.getSize(new T.Vector3()),center=box.getCenter(new T.Vector3());const d=Math.max(size.x/Math.max(.2,camera.aspect),size.z,size.y)*(camera.aspect<1?.61:.43)/Math.tan(T.MathUtils.degToRad(camera.fov/2));orbit.target.copy(center);camera.position.copy(center).add(new T.Vector3(.65,.9,1.2).normalize().multiplyScalar(d));orbit.update();}
